/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

import java.util.Map;
import java.util.Optional;
import java.util.stream.Collectors;

import io.quarkus.arc.Arc;
import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.observe.observedissuealias.domain.ObservedIssueAlias;
import net.civeira.phylax.feature.observe.observedissuealias.domain.gateway.ObservedIssueAliasFilter;
import net.civeira.phylax.feature.observe.observedissuealias.domain.gateway.ObservedIssueAliasQueryRepositoryGateway;

/**
 * Fingerprints of merged issues (observed-issue-alias) in memory: origin + fingerprint → the issue
 * that receives its events. Reloaded every minute and right after a merge.
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class IssueAliases {

  private final ObservedIssueAliasQueryRepositoryGateway aliases;
  private volatile Map<String, String> current = Map.of();

  public Optional<String> issueOf(final String originUid, final String fingerprint) {
    return Optional.ofNullable(current.get(originUid + "\n" + fingerprint));
  }

  public void reload() {
    boolean activated = !Arc.container().requestContext().isActive();
    if (activated) {
      Arc.container().requestContext().activate();
    }
    try {
      current = aliases.list(ObservedIssueAliasFilter.builder().build()).stream()
          .collect(Collectors.toMap(alias -> alias.getOriginUid() + "\n" + alias.getFingerprint(),
              ObservedIssueAlias::getIssueUid, (a, b) -> b));
    } catch (RuntimeException ex) {
      log.warn("Unable to reload the issue aliases: {}", ex.getMessage());
    } finally {
      if (activated) {
        Arc.container().requestContext().terminate();
      }
    }
  }
}
